with filtered as (select id, amount, txn_time, merchant, is_flagged, cast(txn_time as date) as txn_time_day from transactions where txn_time >= timestamp '2023-08-06 04:00:00' and merchant is not null) select merchant, case when amount >= 3800 then 'PREMIUM' else 'STANDARD' end as amount_tier, min(txn_time) as first_seen, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as duration_min, count(case when merchant = 'Lazada' then 1 end) as lazada_count, count(distinct merchant) as distinct_merchants, grouping_id() as gid from filtered group by grouping sets ((merchant, case when amount >= 3800 then 'PREMIUM' else 'STANDARD' end), (merchant)) order by duration_min desc;
